'use client';
import { useState } from 'react';
import AppShell from '../../app/components/app-shell';
import Overview from '../../app/overview/overview';
import Activity from '../../app/activity/activity';
import type { Company, Member } from '../../lib/agent-types';
import type { ActivityData, ActivityEvent, OverviewData } from '../../lib/overview-types';
const companies:Company[]=[{id:'11111111-1111-4111-8111-111111111111',name:'Northstar Demo',time_zone:'Europe/London'},{id:'22222222-2222-4222-8222-222222222222',name:'Westfield Demo',time_zone:'America/New_York'}];
function event(company:Company,id:string):ActivityEvent {return {id,agent_id:'33333333-3333-4333-8333-333333333333',agent_name:company.id===companies[0].id?'Taylor Example':'Casey Sample',actor_user_id:'44444444-4444-4444-8444-444444444444',actor_name:company.id===companies[0].id?'Alex Demo':'Blair Demo',action:'created',revision:1,occurred_at:'2026-10-03T23:30:00Z'};}
export default function Review(){const [company,setCompany]=useState(companies[0]);const [screen,setScreen]=useState<'overview'|'activity'>('overview');const [role,setRole]=useState<Member['role']>('owner');const canViewActivity=role==='owner'||role==='admin';const events=[event(company,'9007199254740993')];const summary:OverviewData={company:{...company,status:'active'},role,canViewActivity,agents:{active:12,archived:3,linked:8,unlinked:4},memberships:{owner:1,admin:2,manager:1,employee:8},recentActivity:canViewActivity?events:[]};const history:ActivityData={events,nextCursor:'synthetic-next-page'};return <AppShell companyName={company.name} companyId={company.id} activeModule="users" accountName="Synthetic reviewer"><div style={{padding:'12px 20px',display:'flex',gap:12,flexWrap:'wrap'}} aria-label="Synthetic review controls"><button onClick={()=>setScreen('overview')}>Review Overview</button><button onClick={()=>setScreen('activity')}>Review Activity</button><button onClick={()=>setCompany(company.id===companies[0].id?companies[1]:companies[0])}>Switch demo company</button><button onClick={()=>setRole(role==='owner'?'manager':'owner')}>Switch demo role</button></div>{screen==='overview'?<Overview company={company} role={role} initialData={summary}/>:<Activity company={company} role={role} initialData={history}/>}</AppShell>;}
